    'Template that defines the field’s custom “translation key” format. Field values will be copied to all sites that produce the same key.' => 'תבנית המגדירה את פורמט “מפתח התרגום” המותאם אישית של השדה. ערכי השדה יועתקו לכל האתרים שמפיקים את אותו המפתח.',
    'Template that defines the {name} field’s custom “translation key” format. Values will be copied to all sites that produce the same key.' => 'תבנית שמגדירה את פורמט "מפתח התרגום" המותאם אישית של השדה {name}. ערכים יועתקו לכל האתרים שמפיקים את אותו המפתח.',
