    'The minimum number of rows the field is allowed to have.' => 'המספר המינימלי של שורות ששדה זה יכול להכיל.',
    'The minimum number of {type} that may be selected.' => 'המספר המינימלי של {type} שעשוי להיבחר.',
    'The minimum number of {type} the field is allowed to have.' => 'המספר המינימלי של {type} ששדה זה יכול להכיל.',
    'The number of minutes that timepicker options should be incremented by. (Authors can enter a specific time manually.)' => 'מספר הדקות בהן יש להגדיל את אפשרויות ה-timepicker. (יוצרים יכולים להזין שעה ספציפית באופן ידני.)',
    'The number of seconds that the Retry-After HTTP header should be set to for maintenance mode responses.' => 'מספר השניות שאליו תוגדר כותרת ה-HTTP ‏Retry-After בתגובות במצב תחזוקה.',
    'The path can contain variables like `{slug}` or `{author.username}`.' => 'הנתיב יכול להכיל משתנים כמו `{slug} או `{author.username}`.',
