    'The selected {type} could not be found.' => 'לא ניתן למצוא את ה-{type} שנבחר.',
    'The server doesn’t meet Craft’s new requirements:' => 'השרת אינו עומד בדרישות החדשות של Craft:',
    'The subpath cannot overlap with any other volumes sharing the same filesystem.' => 'נתיב המשנה לא יכול לחפוף עם כל אמצעי אחסון אחר המשתף את אותה מערכת קבצים.',
    'The template Craft CMS will use for HTML emails' => 'התבנית שבה תשתמש Craft CMS לדואר אלקטרוני HTML.',
