    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'התבנית מקבלת את המשתנים `element` ו-`static`. הפלט שלה מנוקה ומוצג כתוכן לא אינטראקטיבי; פקדי טפסים, סקריפטים ונכסים רשומים אינם נתמכים.',
    'The template will be rendered with an `element` variable.' => 'התבנית תעובד עם משתנה `element`.',
