    'The user photo provided is not an image.' => 'תצלום המשתמש שסופק אינו תמונה.',
    'The user photo provided is not valid.' => 'תמונת המשתמש שסופקה אינה תקינה.',
    'The values are matched inclusively.' => 'הערכים מותאמים באופן כוללני.',
    'The volume where pasted or dropped files should be uploaded.' => 'אמצעי האחסון שאליו יועלו קבצים שהודבקו או נגררו.',
    'The volumes that should be available when selecting assets.' => 'אמצעי האחסון שיהיו זמינים בעת בחירת נכסים.',
