    'The {name} license is invalid.' => 'רישיון ה-{name} לא תקף.',
    'The {numEntries, plural, =1{entry} other {entries}} will be updated once the {numUsers, plural, =1{user is} other{users are}} deleted.' => 'ה{numEntries, plural, =1{רשומה תעודכן} other {רשומות יעודכנו}} לאחר שה{numUsers, plural, =1{משתמש יימחק} other{משתמשים יימחקו}}.',
    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => 'ה{numRelations, plural, =1{קשר יוסר} other {קשרים יוסרו}} לאחר שה-{numTargets, plural, =1{{targetTypeSingular} יימחק} other{{targetTypePlural} יימחקו}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{קיימות הפניות אל ה-{targetTypeSingular}} other{קיימות הפניות אל ה-{targetTypePlural}}} משדות ב-{numSources, number} {numSources, plural, =1{רכיב אחר} other{רכיבים אחרים}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} related by {numRelations, number} other {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}.' => 'ה{numTargets, plural, =1{{targetTypeSingular} קשור/ה} other{{targetTypePlural} קשורים/ות}} על ידי {numRelations, number} {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}} אחר/אחרת/אחרים.',
    'The {type} is invalid.' => 'ה-{type} לא חוקי.',
    'The “From” name Craft CMS will use when sending email.' => 'השם שבו תשתמש template בשורת "מאת" במשלוח דואר אלקטרוני.',
    'Theme' => 'ערכת נושא',
    'There are no available plugins.' => 'אין תוספים זמינים.',
    'There was a problem activating the user: {error}' => 'הייתה בעיה בהפעלת המשתמש: {error}',
