    'This browser doesn’t support passkeys.' => 'הדפדפן אינו תומך במפתחות גישה.',
    'This can be left blank if you just want an unlabeled separator.' => 'באפשרותך להשאיר את זה ריק אם אתה מעוניין במפריד בלי תווית.',
