    'When someone replaces a file, the record of who uploaded the file will be updated as well.' => 'כאשר מישהו מחליף קובץ, התיעוד של מי העלה את הקובץ יעודכן גם כן.',
    'Where assets should be stored (relative to **Asset Location**) when they are uploaded directly to the field.' => 'היכן שנכסים צריכים להיות מאוחסנים (ביחס ל**מיקום הנכס**) כאשר הם מועלים ישירות לשדה.',
