    'Whether authors should be able to choose which time zone the time is in.' => 'האם יוצרי התוכן יוכלו לבחור באיזה אזור זמן נמצא הזמן.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'האם יוצרי תוכן יהיו מסוגלים להעלות קבצים ישירות לשדה, במקום לדרוש מהם לבחור/להעלות נכסים דרך מודול הבחירה.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'האם כפתורים צריכים להציג רק את הסמלים שלהם, ולהסתיר את תוויות הטקסט.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'האם תצוגות כרטיס הכוללות שדה זה יציגו את תוויות ה\'פעיל/כבוי\' המותאמת אישית, במקום את שם השדה.',
    'Whether custom fields should be validated during public registration.' => 'האם שדות בהתאמה אישית צריכים להיות מאומתים בעת הרישום הציבורי.',
